        input.addClass('no-submit');
      }
    },
    focus: function (formId, attrs) {
      $('#' + formId + ' ' + '.' + 'placeholder').focus(function () {
        var target = $(this);
        for (var x = 0; x < attrs.length; x++) {
          if (target.attr('id') == attrs[x].id && target.val() == attrs[x].value) {
