@charset "UTF-8";
.mainImg {
	margin-top: 10px;
}
.topBox {
	margin-top: 60px;
}
.mainImg-bg {width: 100%;}
.mainImg-bg img{width: 100%;height: auto;}
.pcOnly {display: block;}
.spOnly {display: none;}
#seikitoriatsukai-search_ttl {
	width: 100%;
	background-color: #0056A8;
	margin: 20px 0px;
}
#seikitoriatsukai-search_ttl h2 {
	width: 976px;
	margin: auto;
	font-size: 28px;
	font-weight: bold;
	padding: 25px 0px;
	color: #fff;
}
#unicom-seikitoriatsukai_search {
	background: #fff;
}
#unicom-seikitoriatsukai_search section {
	width: 976px;
	margin: auto;
	/*margin-bottom: 50px;*/
	padding-bottom: 50px;
}
#st_kekka_txt h3{
	font-size: 22px;
}
.st_top {text-align: right;}
#st_kekka_txt a {
	font-size: 14px;
}
#st_kekka_txt a img {
	vertical-align: middle;
}
#st_search {
	margin: 30px 0px;
}
#st_search p{font-size: 32px;}
#st_search form {
	width: 100%;
	background-color: #E0F6FF;
	padding: 30px 0px;
	margin-top: 20px;
}
.st_search_box {
	display: flex;
	justify-content: center;
	margin: 10px 0px;
}
.st_search_box_inner {
	width: 40%;
	padding: 0px 20px;
}
#st_search .st_search_box .st_search_box_inner label {
	font-size: 30px;
}
#st_search select {/* 初期化 */
  appearance: none;
  -moz-appearance: none;
  -webkit-appearance: none;
  background: none;
  border: none;
  color: #333;
  font-size: 16px;
  width: 100%;
  height: 100%;
  padding: 0 10px;
}
#st_search select { 
	width: 100%;
	height: 50px;
	background-color: #fff;
	border: solid 1px #ccc;
	border-radius: 0px;
}
#st_search .arrow {
  position: relative;
  display: inline-block;
	width: 100%;
}
#st_search .arrow::before {
  content: '';
  width: 10px;
  height: 10px;
  border-top: solid 2px #999;
  border-right: solid 2px #999;
  position: absolute;
  right: 15px;
  top: 15px;
}
#st_search .arrow.arrow-bottom::before {
  transform: rotate(135deg);
}
#st_search option[selected][disabled] {
  display: none;
}
.st_search_box_bd {border-right: solid 1px #999;}
#st_search .st_search_box_inner #sbox2 {
	appearance: none;
	-webkit-appearance: none;
    -moz-appearance: none;
	width: 100%;
	height: 50px;
	background-color: #fff;
	border: solid 1px #ccc;
	border-radius: 0px;
	margin-top: 20px;
	padding-left: 10px;
	font-size: 15px;
}
.st_search_box_inner label {vertical-align: bottom;}
.st_search_box_inner label img{
	width: 30px;
	height: 30px;
	padding-right: 3px;
}
.txt_center {
	text-align: center;
}
#st_search .st_search_btn {
	width: 200px;
	height: 50px;
	background-color: #0056A8;
	border: none;
	border-radius:25px;
	font-size: 24px;
	color: #fff;
	margin: auto;
	margin-top: 15px;
}
#st_search .st_search_btn:hover{
	opacity: 0.5;
	transition-duration: 0.3s;
}
#st_kekka_box {
	width: 750px;
	margin: 50px auto;
}
#st_kekka_box p {
	font-size: 16px;
	line-height: 1.5em;
}
#st_kekka_table {
	margin: 10px 0px;
}
#st_kekka_table table {
    width: 100%;
    border: solid 1px #000;
    background-color: #FFFFFF;
}
#st_kekka_table table tr {
	display: block;
	padding: 15px;
	border-top: solid 1px #000;
}
#st_kekka_table td {
    width: 100%;
    display: inline-block;
}
#st_kekka_table th {
	font-size: 28px;
}
.st_shopname {
	font-size: 18px;
}
.st_taisyo {
	font-size: 90%;
	color: #fc1921;
}
.txt_r { 
	text-align: right;
}
#st_kekka_table table tr.br_none {
	border-top: none;
}
.st_kekka_item_re {
	position: relative;
}
.st_kekka_item_ab {
	position: absolute;
	bottom: 0px;
	right: 0px;
}
@media only screen and (max-width:640px) and (max-device-width:1280px){
.pcOnly {display: none;}
.spOnly {display: block;}	
	#unicom-seikitoriatsukai_search	{
		width: 100%;
		max-width: 100%;
