#st_kekka_txt h3{
	font-size: 18px;
	margin-bottom: 5px;
}
.st_top {text-align: right;}
#st_kekka_txt a {
	font-size: 12px;
}	
#st_search p{font-size: 24px;}
#st_search form {
	width: 100%;
	/*background-color: #FFFFCC;*/
	background-color: #E0F6FF;
	padding: 15px 0px;
	margin-top: 20px;
}
.st_search_box {
	flex-flow: column;
}
.st_search_box_inner {
	width: 90%;
	padding: 20px 0px;
	margin: auto;
}
#st_search .st_search_box .st_search_box_inner label {
	font-size: 24px;
}
#st_search .st_search_box .st_search_box_inner label img{
	width: 20px;
	height: 20px;
	padding-right: 3px;
}
.st_search_box_bd {
	border-right: none;
	border-bottom:  solid 1px #999;
	}	
#st_kekka_box {
	width: 100%;
	margin: 50px auto;
}
.st_kekka_item_re {
	position: relative;
}
.st_kekka_item_ab {
	position: absolute;
	bottom: 0px;
	right: 0px;
}
	.moji_nowrap {
		white-space: nowrap;
	}
}

#od_search {
	margin: 80px 0px 50px;
	background-color: #DFF9CE;
}
#od_search .od_search_inner {
	padding: 50px 80px 30px;
}
#od_search h2{
	font-size: 30px;
}
#od_search h2 img{
	width: 30px;
	height: 30px;
	padding-right: 3px;
	vertical-align: bottom;
}
#od_search .od_search_box {
	width: 100%;
	padding: 30px 0px 0px;
	display: flex;
	flex-wrap: wrap;
	justify-content: space-between;
