  }
  .holdings-header .holdings-header__fixarea.fix .holdings-header__company:not(.inpanel) {
    visibility: hidden;
    height: 0;
    min-height: 0;
    padding: 0 15px;
    border: none;
  }
}
/* header brand */
.holdings-header__brand {
  display: flex;
  justify-content: center;
  align-items: center;
  box-sizing: border-box;
