  background: url(common-clientlibs/images/img-nav-expanded.jpg) no-repeat center top gray;
}

#navmenucat .hide {
  height: 276px;
  display: none;
}

#navmenucats a {
  font-family: 'Open Sans Condensed', 'Arial', sans-serif;
  font-size: 13px;
  color: #b6b6b6;
  font-weight: bold;
  line-height: 19px;
  text-decoration: none;
}

#navmenucats a:hover {
  color: #fff;
}

#navmenucats .panhead {
  height: 40px;
  margin: 0 auto;
  border-bottom: 1px solid #636363;
}

#navmenucats .inbread {
  margin-top: 15px;
  float: left;
}

#navmenucats .inbread span {
  font-family: 'Open Sans Condensed', 'Arial', sans-serif;
  font-size: 13px;
  color: #fff;
  font-weight: bold;
  line-height: 19px;
  display: inline-block;
  margin-right: 10px;
}

#navmenucats .inbread span a {
  background: url(common-clientlibs/images/icn-nav-global-arrow-right.gif) no-repeat 100% 50%;
  padding-right: 17px;
}

#navmenucats .closeit {
  float: right;
}

#navmenucats .closeit a {
  display: block;
  width: 9px;
  height: 9px;
  margin-top: 15px;
}

#navmenucats .parrays {
  position: relative;
  width: 992px;
  height: 169px;
  margin: 20px auto 0;
  text-align: center;
}

#navmenucats .parrays ul {
  position: absolute;
  left: 0;
  font-size: 0;
  width: 992px;
  text-align: center;
}

#navmenucats .parrays li {
  display: inline-block;
  margin-right: 1px;
  text-align: center;
  vertical-align: top;
  width: 123px;
}

#navmenucats .parrays ul > li:last-child {
  margin-right: 0px;
}

#navmenucats .parrays li a {
  display: inline-block;
}

#navmenucats .parrays li .img-element {
  display: block;
  padding-bottom: 15px;
}

#navmenucats .parrays li .catname {
  display: block;
  padding: 0 3px;
}

#navmenucats .parrays li ul .parbase {
  display: none;
}

#navmenucats .panfoot {
  height: 47px;
  font-family: 'Open Sans Condensed', 'Arial', sans-serif;
  font-size: 13px;
  color: #b6b6b6;
  font-weight: bold;
  line-height: 19px;
  border-top: 1px solid #636363;
}

#navmenucats .panfoot .browseall {
  margin-top: 15px;
  float: right;
}

#navmenucats .panfoot .browseall a {
  display: inline-block;
  background: url(common-clientlibs/images/icn-browse-products.png) no-repeat 0 50%;
  padding-left: 21px;
}

